// GENERATED FILE — do not edit. Regenerate with npm run content:generate.
import type { QuizQuestion } from '../../core/combat/QuizQuestion';

export const questions: readonly QuizQuestion[] = [
  {"id":"q-dr-01","prompt":"The foreman taps the retired rack against the wall, labelled 'before', and waits for you to read the label. What did the tiny switches replace?","options":["vacuum tubes","integrated circuits","microprocessors","multi-core CPUs"],"correctOptionIds":[0],"explanation":"The foreman gives the retired rack against the wall a fond thump. It is what the tiny switches replaced: vacuum tubes came first, and the switches made computers smaller, faster and more reliable. The other three are later arrivals on this floor; none came before the switches."},
  {"id":"q-dr-02","prompt":"The foreman folds his arms by the 'before' rack. Which statement about the tiny switches matches what he says about it?","options":["They replaced vacuum tubes, making computers smaller, faster and more reliable.","They replaced integrated circuits, making computers smaller, faster and more reliable.","They appeared after microprocessors, making computers smaller, faster and more reliable.","They replaced vacuum tubes, making computers larger, slower and less reliable."],"correctOptionIds":[0],"explanation":"The foreman reads the retired rack aloud, plainly: the early switches replaced vacuum tubes and made computers smaller, faster and more reliable. The sign by the belt adds that the modern ones arrive packed onto chips; microprocessors and multi-core CPUs are later still. The last option gets the component right but reverses every stated effect."},
  {"id":"q-dr-03","prompt":"The foreman points to one black switch on the belt and clicks it once, twice, for emphasis. Set one way or the other, it decides whether a line carries one or zero. Which machine part is that?","options":["a transistor used as a switch, choosing one or zero","a vacuum tube used as a switch, choosing one or zero","an integrated circuit used as a switch, choosing one or zero","a byte used as a switch, choosing one or zero"],"correctOptionIds":[0],"explanation":"The foreman flips the black switch once more. A transistor acts as a tiny switch, which is why this floor is built out of switches; the retired rack of vacuum tubes is the earlier technology the switches replaced. The sign by the belt speaks of many transistors packed onto a chip rather than one switch, and a byte is a unit of eight bits rather than a component."},
  {"id":"q-dr-04","prompt":"The foreman nudges the hall's 'age 15' bin with his boot. It holds a whole number. Which data type fits it?","options":["integer","real","character","Boolean"],"correctOptionIds":[0],"explanation":"The foreman tips the bin towards you. The 'age 15' sample is an integer: a whole number, positive or negative. A real has a decimal point, a character is one number, letter or symbol, and a Boolean is a logical comparison."},
  {"id":"q-dr-05","prompt":"The foreman points to the bin labelled 'if Valid = True'. Which data type fits it?","options":["Boolean","integer","string","real"],"correctOptionIds":[0],"explanation":"The foreman lifts the flap of paper: the bin labelled 'if Valid = True' is the Boolean one, used for logical comparisons or conditions. Integers, strings and reals hold values rather than a True/False condition."},
  {"id":"q-dr-06","prompt":"The hall's sixth bin has no label yet. The foreman hands you a tile marked 'A'. Which bin and data type fit?","options":["the character bin: 'A' is a single letter","the string bin: 'A' is a sequence of characters","the integer bin: 'A' is a whole number","the Boolean bin: 'A' is a condition"],"correctOptionIds":[0],"explanation":"The foreman slides the tile marked 'A' across the bench. A character is a single number, letter or symbol, and the bin marked 'A' is exactly that. A string is a sequence of characters, like the email bin's label; a single letter is neither a whole number nor a True/False condition."},
  {"id":"q-dr-07","prompt":"The foreman sweeps a hand along the hall's board of samples. Which one is a real rather than an integer?","options":["temperature = 36.4","age = 15","letter = 'A'","if Valid = True"],"correctOptionIds":[0],"explanation":"The foreman rests a finger on the 'temperature 36.4' bin. A real is a number with a decimal point, and that is the one. 'age 15' is the integer, 'A' the character and 'if Valid = True' the Boolean."},
  {"id":"q-dr-08","prompt":"The clerk sets a fresh card on the desk. 'Convert denary 37 to binary.' Which bit pattern results?","options":["101001","100110","100100","100101"],"correctOptionIds":[3],"explanation":"The clerk sets the card square. Divide by 2 and record the remainder each time, then reverse the order: the remainders 1, 0, 1, 0, 0, 1 reversed give 100101. 101001 is those same remainders written without reversing; 100110 and 100100 are off-by-one slips at the final remainder."},
  {"id":"q-dr-09","prompt":"The clerk writes 10100101 on the card and squares it up with the edge of the desk. Convert it to hexadecimal by grouping into fours from the right. Which value results?","options":["5A","AA","55","A5"],"correctOptionIds":[3],"explanation":"The clerk draws a neat line between the two groups. Group from the right: 1010 = 10 = A and 0101 = 5, so the value is A5. 5A swaps the two groups; AA reads both groups as 1010; 55 reads both as 0101."},
  {"id":"q-dr-10","prompt":"The clerk points to the carry track, where the rightmost column holds 1 and 1. What does the painted rule put in that column and in the next one?","options":["1 in the column, carry 1 to the next","10 in the column, carry 0 to the next","0 in the column, carry 0 to the next","0 in the column, carry 1 to the next"],"correctOptionIds":[3],"explanation":"The clerk points to the painted rule. It is 1 + 1 = 10, meaning 0 in the column with a carry of 1 added to the next column. Writing 10 inside one column misses the carry step; 1 in the column borrows the rule for 1 + 1 + 1; carrying 0 drops the carry altogether."},
  {"id":"q-dr-11","prompt":"The clerk slides the switches along the arrow-notched gutter and watches the last bit drop into the tin tray at the end. 'Well?' he says. Which pair of ideas fits the gutter and the tray?","options":["binary addition, then underflow","an arithmetic shift, then underflow","binary addition, then overflow","an arithmetic shift, then overflow"],"correctOptionIds":[3],"explanation":"The clerk watches the bit land in the tray. The gutter is where you use an arithmetic shift and explain its effect. A bit running past the last switch into the tray is overflow; underflow is the other idea on offer, and it does not match this falling bit. Binary addition belongs to the carry track rather than the gutter."},
  {"id":"q-dr-12","prompt":"The typesetter lifts the stamp's case lid and tilts it towards you. A definition is written inside. Which two character sets does it name as standardised?","options":["binary and denary","ASCII and Unicode","JPEG and PNG","WAV and FLAC"],"correctOptionIds":[1],"explanation":"The typesetter tilts the lid so you can read it. It names Unicode and American Standard Code for Information Interchange (ASCII) as standardised character sets for storing characters digitally. Binary and denary are counting systems; JPEG, PNG, WAV and FLAC belong to compression rather than the tile case."},
  {"id":"q-dr-13","prompt":"The typesetter sets one tile and one blank label in front of you: a single symbol 'A' for the tile, the word 'Wales' for the label. Which data types fit, in that order?","options":["string, then character","integer, then real","character, then string","Boolean, then string"],"correctOptionIds":[2],"explanation":"The typesetter sets the tile and the label side by side. A character is a single number, letter or symbol, so 'A' is a character; a string is a sequence of characters, so 'Wales' is a string. Swapping the two misses the single-versus-sequence distinction; integers, reals and Booleans do not store letters or words."},
  {"id":"q-dr-14","prompt":"The typesetter holds up one tile from the case. It holds a single number, letter or symbol. Which data type is that?","options":["Boolean: logical comparisons or conditions","character: a single number, letter or symbol","string: a sequence of characters","integer: whole numbers, positive and negative"],"correctOptionIds":[1],"explanation":"The typesetter turns the tile over in his fingers. A character is a single number, letter or symbol, and the tile marked 'A' is the case's own example of one. A string is several characters, an integer is a whole number and a Boolean is a True/False condition."},
  {"id":"q-dr-15","prompt":"In the character case each mark has its own tile, down to a spare kept in a drawer. The typesetter closes the lid gently. What is being stored digitally here?","options":["graphics, stored as pixels","sound, stored as samples","characters, using standardised character sets","a compression ratio, original over compressed"],"correctOptionIds":[2],"explanation":"The typesetter closes the lid gently over the spare drawer. This is the digital storage of characters using standardised character sets, which the stamp's case lid names as ASCII and Unicode. Pixels belong to the mosaic, samples to the choir, and a ratio to the press. The case lid does not say which set covers any particular mark, so nothing here hangs on the spare tile's symbol."},
  {"id":"q-dr-16","prompt":"The critic draws you to the drafting corner and traces a smooth curve in the air. How are those curves stored?","options":["as a grid of pixels with colour values","using mathematics, such as lines and curves","as measurements taken at time intervals","as an index file of redundancies"],"correctOptionIds":[1],"explanation":"The critic traces the curve again with one finger. A vector uses mathematical representations of geometrical objects such as lines and curves, which is why the drafting corner's curves stay smooth. Pixels with colour values describe the mosaic's raster side, time-interval measurements belong to the choir, and an index file is part of lossless compression."},
  {"id":"q-dr-17","prompt":"In the drafting corner the smooth curves grow larger while the pixel grid beside them squares off. The critic raises an eyebrow. Which statement explains what you see?","options":["vector, because maths can scale without apparent quality loss","raster, because each pixel keeps its colour value","raster, because higher resolution means higher quality","neither, because scaling always changes quality"],"correctOptionIds":[0],"explanation":"The critic watches the curve hold as it grows. The curves stay smooth because a vector can be scaled up without loss of apparent quality. A raster image stores a colour value in each pixel, and higher resolution does raise quality and file size; neither makes a pixel grid scale cleanly, and the last option denies the vector property altogether."},
  {"id":"q-dr-18","prompt":"The critic points to a label in the mosaic: an RGB image, '8-bit colour depth'. He waits. What does that mean here?","options":["8 bits for the whole pixel, as in older bpp systems","8 bits for each of red, green and blue","8 bits for the red channel only","24 bits for each of red, green and blue"],"correctOptionIds":[1],"explanation":"The critic taps the label twice. Colour depth is given in bits per channel (bpc): 8-bit RGB means 8 bits for red, 8 for green and 8 for blue. Older systems used bits per pixel (bpp), so the whole-pixel reading belongs to that older convention; 24 bits is the combined total across the three channels rather than the value of each."},
  {"id":"q-dr-19","prompt":"One mosaic image measures 1920 × 1080 with 8-bit RGB, at 24 bits per pixel. The critic rests the ruler on the frame. How many bits are stored in the whole image?","options":["49,766,400","16,588,800","6,220,800","2,073,600"],"correctOptionIds":[0],"explanation":"The critic sets the ruler along the frame. Resolution gives 2,073,600 pixels and 24 bits per pixel, so the total is 2,073,600 × 24 = 49,766,400 bits. 16,588,800 uses only the 8-bit depth; 6,220,800 is the byte total after dividing by 8; 2,073,600 is the pixel count alone."},
  {"id":"q-dr-20","prompt":"The choirmaster taps a card by the bit-rate desk and waits. What is a sample, as that card has it?","options":["a single measurement of sound at a point in time","the number of audio channels in the recording","the number of bits used to record each sample","the data processed per second of sound"],"correctOptionIds":[0],"explanation":"The choirmaster turns the card face up. It defines a sample as a single measurement of sound taken at a specific point in time. Channels, bit depth and bit rate are the other quantities on that card rather than the sample itself."},
  {"id":"q-dr-21","prompt":"The choirmaster sets two recordings side by side: one on a single audio channel, one on two. Which counts do those correspond to?","options":["mono = 2, stereo = 1","mono = 1, stereo = 4","mono = 0, stereo = 2","mono = 1, stereo = 2"],"correctOptionIds":[3],"explanation":"The choirmaster points from one recording to the other. Mono is 1 channel and stereo is 2. Swapping the counts, inventing a fourth channel or giving mono no channel all break that."},
  {"id":"q-dr-22","prompt":"The bit-rate desk has dials for samples per second and bits per sample. The choirmaster turns one, then the other. How do you find the bit rate?","options":["divide the sample rate by the bit depth","multiply the bit depth by the channel count","multiply the sample rate by the bit depth","multiply the sample rate by the duration"],"correctOptionIds":[2],"explanation":"The choirmaster lets go of the dials. Bit rate is the amount of data processed per second of sound and is found by multiplying the sample rate by the bit depth. Multiplying by duration belongs to the total-storage calculation, and the other options misuse the desk's quantities."},
  {"id":"q-dr-23","prompt":"The choirmaster reads out the choir's own figures — stereo, 44.1 kHz, 16-bit depth, three minutes — and folds his arms. Which expression gives the total bits stored?","options":["44,100 × 16 × 180","44.1 × 16 × 2 × 180","44,100 × 2 × 180","44,100 × 16 × 2 × 180"],"correctOptionIds":[3],"explanation":"The choirmaster lowers his hand. Storage size is sample rate × bit depth × channels × duration. That means 44,100 samples per second, 16 bits per sample, 2 channels for stereo and 180 seconds. The first option omits channels, the third omits bit depth, and the second uses the kHz label instead of 44,100 samples per second."},
  {"id":"q-dr-24","prompt":"The stack keeper wipes the brass plate on the stacks and clears his throat. It gives one plain figure. How many bytes are in one kilobyte?","options":["1,024","1,000","512","8"],"correctOptionIds":[0],"explanation":"The stack keeper polishes the brass plate with his sleeve. It states that one kilobyte holds 1,024 bytes. 1,000 is the decimal reading the ladder excludes; 8 is the number of bits in a byte; 512 is half a kilobyte."},
  {"id":"q-dr-25","prompt":"The stack keeper sets a foot on the bottom rung of the ladder in the stacks. Which sequence matches its rungs?","options":["bit → byte → nibble → KB → MB → GB → TB → PB","bit → nibble → byte → KB → MB → GB → TB → PB","bit → nibble → byte → KB → MB → GB → PB → TB","byte → nibble → bit → KB → MB → GB → TB → PB"],"correctOptionIds":[1],"explanation":"The stack keeper rests a foot on the bottom rung. The ladder runs bit, nibble, byte, kilobyte, megabyte, gigabyte, terabyte, petabyte, each rung from byte upward holding 1,024 of the one below. The other options swap nibble and byte, swap the final two rungs, or reverse the opening three."},
  {"id":"q-dr-26","prompt":"The stack keeper nods at a shelf. It holds 3 KB. 'How many bytes?' he asks, already reaching for the ledger.","options":["3,072","3,000","24","1,024"],"correctOptionIds":[0],"explanation":"The stack keeper opens the ledger at a fresh page. Each KB holds 1,024 bytes, so 3 KB holds 3 × 1,024 = 3,072 bytes. 3,000 uses a decimal thousand; 24 mistakes the count for bits (3 × 8); 1,024 is a single KB rather than three."},
  {"id":"q-dr-27","prompt":"A crate sits by the stack keeper's open arch. It holds 2 GB. How many MB is that?","options":["2,000","1,024","16,384","2,048"],"correctOptionIds":[3],"explanation":"The stack keeper checks the crate's stamped label. One gigabyte holds 1,024 megabytes, so 2 GB holds 2 × 1,024 = 2,048 MB. 2,000 uses decimal prefixes; 1,024 is only one GB; 16,384 comes from wrongly bringing the eight-bits-per-byte factor into a byte-to-byte conversion."},
  {"id":"q-dr-28","prompt":"The press operator sweeps a hand over the tray of format labels. Which list gives the lossy compression formats?","options":["MP3, JPEG, MPEG","WAV, PNG, FLAC","JPEG, PNG, BMP","ASCII, Unicode, RGB"],"correctOptionIds":[0],"explanation":"The press operator fans the format labels out on the tray. MP3, JPEG and MPEG are the lossy formats. WAV, PNG, BMP and FLAC are the lossless ones; the third list mixes the two, and ASCII, Unicode and RGB belong to the tile case and the colour model rather than the press."},
  {"id":"q-dr-29","prompt":"The press operator holds two files, one in each hand, and waits. What does lossless compression offer that lossy compression does not?","options":["It reduces the file more than lossy compression does.","It can be uncompressed back to its original form.","It removes detail the user is unlikely to notice.","It lowers the quality so the file shrinks further."],"correctOptionIds":[1],"explanation":"The press operator weighs one file in each hand. Lossless compression maintains quality and enables the file to be uncompressed to its original form, which lossy compression cannot do. Lossy generally reduces size by a greater amount and removes data considered less important, at the cost of quality."},
  {"id":"q-dr-30","prompt":"The press operator points out the ratio window: an original column and a compressed column. How is the compression ratio worked out?","options":["original size ÷ compressed size","compressed size ÷ original size","original size − compressed size","original size × compressed size"],"correctOptionIds":[0],"explanation":"The press operator jabs a finger at the ratio window. It gives compression ratio = original data size / compressed data size. Reversing the division, subtracting or multiplying all change both the value and the meaning of the ratio."},
  {"id":"q-dr-31","prompt":"On the ratio window's sample tray the original size is 1000 and the compressed size is 200. The press operator waits with the stub of a pencil. Which expression gives the compression ratio?","options":["200 ÷ 1000, written 2:10","1000 − 200, written 800:1","1000 × 200, written 200,000:1","1000 ÷ 200, written 10:2"],"correctOptionIds":[3],"explanation":"The press operator reads the two figures off the tray. The ratio is original ÷ compressed, so 1000 ÷ 200, which the window shows as 10:2. Reversing the division, subtracting or multiplying do not follow that definition."},
  {"id":"q-dr-32","prompt":"The press operator feeds a 2000 KB file in at a ratio of 10:2 and steps back from the lever. What is the compressed file size?","options":["10,000 KB","200 KB","1,000 KB","400 KB"],"correctOptionIds":[3],"explanation":"The press operator takes his hand off the lever. Compressed size = original size ÷ compression ratio, so 2000 ÷ (10 ÷ 2) = 400 KB. 10,000 KB comes from applying the original-size formula in the wrong direction; 200 KB divides by 10 alone; 1,000 KB simply halves the original."},
  {"id":"q-pc-01","prompt":"The Bureau's common terms card calls pseudo-code an informal way of writing an algorithm. What does pseudo-code demand of the writer?","options":["No strict programming-language syntax at all","A strict programming-language syntax, or the loom refuses the card","Syntax exactly matching one real programming language","A working program that already runs on the mill's loom"],"correctOptionIds":[0],"explanation":"Pseudo-code is an informal way of writing an algorithm: plain words that record the steps, with no strict programming-language syntax to satisfy. It is a draft to be read and corrected by people, never code for the loom to run."},
  {"id":"q-pc-02","prompt":"On the Bureau's stencilled shapes, the slanted rectangle stands for one job only. What does a parallelogram mean on a flowchart?","options":["A decision","Input or output","Start or end of the procedure","The flow of control"],"correctOptionIds":[1],"explanation":"The slanted parallelogram is the flowchart's symbol for input and output. The diamond asks a question, the rounded terminator marks start or end, and the plain rectangle carries an operation or process - judge each symbol by the meaning the table gives it, never by which shape looks busiest."},
  {"id":"q-pc-03","prompt":"A pattern card reads \"call calcAverage\" mid-algorithm, and the subroutine calcAverage was declared earlier. What does that single line do?","options":["It declares a brand-new subroutine","It runs the named subroutine and returns to the main algorithm","It stores the word calcAverage in a variable","It ends the whole algorithm"],"correctOptionIds":[1],"explanation":"The line call calcAverage runs the subroutine named calcAverage and returns to the main algorithm at the point it left. Calling is different from declaring: Declare ... End sets the sub-program up, and call simply hands control to it where its work is needed."},
  {"id":"q-pc-04","prompt":"In the Bureau's pseudo-code, a line inside braces such as \"{Comment on code}\" appears. What is it?","options":["An annotation for the human reader that the algorithm ignores","An instruction the loom weaves like any other line","A value the algorithm keeps and outputs later","A hidden condition that must be true before the algorithm runs"],"correctOptionIds":[0],"explanation":"Braces mark an annotation: a note for the human reader that sits outside the algorithm's work. The loom carries out the lines around it; the note is there to be read, never to be carried out."},
  {"id":"q-pc-05","prompt":"The Warp Dresser's terms card names the first construct. What does sequence ask of an algorithm's steps?","options":["The steps may run in any order the weaver finds tidy","The steps run one after another, in the order they are written","All the steps run at the same time on parallel looms","The steps run only when a condition becomes true"],"correctOptionIds":[1],"explanation":"Sequence keeps the steps one after another, each carried out in the order the card writes them. Change the order and the cloth changes with it, even though every step is still on the card - that is the lesson the cousin's crossed dressing lines left behind (L1253)."},
  {"id":"q-pc-06","prompt":"A test card reads: hue = 2, then hue = hue + 3, then hue = hue * 2, then output hue. What appears on the loom's read-out?","options":["2","5","7","10"],"correctOptionIds":[3],"explanation":"Dry-run the card in order: 2, then 2 + 3 = 5, then the doubling line turns the 5 into 10. A trace that stops at the second line gives 5, and one that re-adds the first value gives 7; each line works on whatever the line before it left stored."},
  {"id":"q-pc-07","prompt":"The Bobbin Window's despatch printer prints Average: and then no number. Which line fault leaves the value empty at the moment it is printed?","options":["The card prints the average before it reads any weight in","The card reads the weights in before it adds them up","The card counts the weights with a loop before printing","The card declares its variables before it uses them"],"correctOptionIds":[0],"explanation":"An output line shows only what is stored when it runs. If the card prints the average before any weight has been read in, nothing is stored for it to show, so the heading stands alone. Reading in, totalling, then printing last is the order that fills the value."},
  {"id":"q-pc-08","prompt":"A crossed card at the Bureau's desk reads output shade first, then input shade. Which two lines mend it, in the right order?","options":["input shade, then input shade again","output shade first, so the loom knows what to expect","input shade, then output shade","declare shade, then output shade, and let the input wait"],"correctOptionIds":[2],"explanation":"The value has to be read in before there is anything to show: input shade stores what the window hands over, and only then does output shade print it. Declaring sets a name up but never stores a window's value, and no number of outputs conjures one."},
  {"id":"q-pc-09","prompt":"Which pseudo-code lines give the Shed Opener exactly two routes to pick between?","options":["for i = 1 to 10 ... next i","repeat ... until the pick is done","if ... else ... end if","while the loom runs ... repeat"],"correctOptionIds":[2],"explanation":"Selection offers a choice of two routes: if the condition holds one part runs, otherwise the else part runs. The for and repeat forms repeat work, and while tests a condition to keep a loop turning, not to route a single pick between two sheds (L1255)."},
  {"id":"q-pc-10","prompt":"The shed plate lifts every pick whose shade register reads 50 or more. A pick's register reads exactly 50. Which condition sends it up?","options":["shade > 50","shade >= 50","shade <> 50","shade < 50"],"correctOptionIds":[1],"explanation":"The rule lifts 50 or more, so the condition must include 50 itself, and >= does that. A strict > stops just short and leaves the 50 pick below, <> picks out everything except 50, and < keeps the low registers down."},
  {"id":"q-pc-11","prompt":"The case rail reads: case select shade, case \"madder\", case \"morpho\", case \"weld\", end case select. A tray's shade is madder. Which case takes the tray?","options":["The madder case and the morpho case both","The first case on the rail, whatever it reads","No case, and the tray waits at the rail's end","The case that names madder, and only that one"],"correctOptionIds":[3],"explanation":"A case select compares the value once and runs the single case that matches it. No neighbouring case opens, and a matched shade never falls through to the cases after it; the other trays stay exactly where their own shades send them (L1255)."},
  {"id":"q-pc-12","prompt":"The cousin's plate keeps the if for the urgent pick but the else for the routine one is gone. What happens to a routine pick?","options":["No branch runs, so the pick is never routed","The if part runs, and the pick stamps urgent","The algorithm stops and waits for the routine branch","Both branches run, urgent and routine together"],"correctOptionIds":[0],"explanation":"Selection runs exactly one branch, and only when its condition holds. With no else, a routine pick satisfies no condition, so no branch runs and the pick waits unsorted - the pile that grew into the shed's trouble (L1255)."},
  {"id":"q-pc-13","prompt":"The counting ratchet's card reads for i = 1 to 10 ... next i, and the shuttle makes one pass for each value i takes. How many passes?","options":["9","10","11","The loom never stops passing"],"correctOptionIds":[1],"explanation":"i takes every value from 1 to 10, counting both ends, so the shuttle passes exactly ten times. Reading the to as leaving the end value out gives 9 - the very slip the ratchet's missing tooth made look true (L1217)."},
  {"id":"q-pc-14","prompt":"Which line, placed inside the loop, raises the Weft Tally's count by one on every pass?","options":["count = count + 1","count = 1","count = i","if count = 1 then"],"correctOptionIds":[0],"explanation":"The incremental count takes the value count already holds, adds one, and stores the result back in count, so it grows once per pass. count = 1 holds it at one, count = i stores the pass number instead of a tally, and if count = 1 then asks a question rather than storing anything (L1259)."},
  {"id":"q-pc-15","prompt":"The bailing beat loads 26 sacks into bundles of 4. What does 26 MOD 4 tell the Weft Tally?","options":["6, the whole bundles","6.5, the exact share","2, the sacks left over","4, the bundle size"],"correctOptionIds":[2],"explanation":"Four into 26 goes six whole times, and six bundles of four hold 24 sacks, so 2 sacks stay loose - MOD answers exactly that left-over part. DIV would answer 6, the whole bundles, and no operator here reports the decimal share (L1292-1293)."},
  {"id":"q-pc-16","prompt":"A tally card reads count = 0, then for i = 1 to 10 ... next i with the line count = count + 2 inside it. What does count hold after the loop?","options":["10","12","20","100"],"correctOptionIds":[2],"explanation":"The loop runs ten times and every pass adds 2, so the tally climbs 2, 4, 6 ... up to 20. Reading only the pass count gives 10, adding the 2 a single time gives 12, and multiplying the ten passes by themselves gives 100; none of those follows 2 added ten times over (L1259)."},
  {"id":"q-pc-17","prompt":"The Warden's corridor-loom must weave its edge at least once before any test. Which construct tests its condition after the body has run?","options":["for i = 1 to 10 ... next i","repeat ... until","while ... repeat","case select ... end case select"],"correctOptionIds":[1],"explanation":"repeat ... until runs its body first and tests at the end, so the body always runs at least once. while ... repeat tests before the body, so a false condition on the first test leaves the body unrun, and a for loop fixes its span before it starts (L1218-1221)."},
  {"id":"q-pc-18","prompt":"A thread dyed a colour that never arises in this pattern carries the reading -1, and the pick loop stops when it reaches it. What does the -1 mean to the loom?","options":["A shade darker than any natural dye","A counting mistake the loom must never meet","A signal the pattern chose, meaning the line may end","A strength reading to add into the pass tally"],"correctOptionIds":[2],"explanation":"The -1 is a rogue value: a signal the pattern's writer chose that never arrives as real data, its only work to end the line. It is not a shade to store or a strength to tally, and the loop tests for it rather than stumbling on it (L1261)."},
  {"id":"q-pc-19","prompt":"The compound plate reads until the pick is done AND the edge is signed. The pick is done; the edge is not signed. What does the loop do?","options":["The loop goes round again","The loop ends, because one job is finished","The loop ends only if the pick was the last one","The loop halts and files a fault with the board"],"correctOptionIds":[0],"explanation":"AND holds only when both sides are true. The finished pick is true but the unsigned edge is false, so the whole condition is false, the until is not satisfied, and the loop goes round again (L1299)."},
  {"id":"q-pc-20","prompt":"The Warden asks: which loop can end having woven nothing at all, if its condition is false on the first test?","options":["repeat ... until, because the until test comes first","for i = 1 to 10 ... next i, for any span the card names","case select, when no case matches the shade","while ... repeat, whose test comes before the body"],"correctOptionIds":[3],"explanation":"A while loop tests before the body and skips the body entirely if the condition is false on the first test. The until test sits after the body, so a repeat always weaves at least one pass, and a for loop's span fixes its passes before it starts (L1221 against L1218)."},
  {"id":"q-pc-21","prompt":"The rail's fresh problem: check all 60 named pegs in turn, the count is known in advance, and the card must count its own passes one to sixty. Which construct heads the card?","options":["repeat the check ... until every peg is checked","for i = 1 to 60 ... next i","case select peg ... end case select","if peg is checked ... else ... end if"],"correctOptionIds":[1],"explanation":"The count is known before the loom starts and the card must name its passes one to sixty, so the count-controlled for loop fits: its control variable walks the pegs in order. Repeat and while wait on a condition and never name a pass count, and case select routes a single value rather than repeating work (L1257-1261)."},
  {"id":"q-pc-22","prompt":"The rail's card reads total = 0, then for i = 1 to 4 ... next i with total = total + i inside the loop, then output total. What is printed?","options":["4","6","10","15"],"correctOptionIds":[2],"explanation":"The tally folds in each pass number as the loop counts: 1, then 3, then 6, then 10. Printing the pass count (4), stopping after the third pass (6), or folding a fifth pass into the tally (15) all walk past the 10 the four passes reach (L1259)."},
  {"id":"q-pc-23","prompt":"The Finished Rail joins the day's work into one algorithm. Which order does the joined card follow?","options":["Input, compute, output","Output, compute, input","Compute, input, output","Input, output, compute"],"correctOptionIds":[0],"explanation":"The joined algorithm reads its values in, works on them, then shows the result. Every other order asks the card to show or to work on values it has not yet read - the empty Average: print on the cousin's despatch card is what that order leaves (L1167, L1251)."},
  {"id":"q-pc-24","prompt":"The cousin's despatch card prints Average: and no number, ten times over. Which card mends it?","options":["Print the average before the first weight is read, then read the ten weights in","Read all ten weights in, adding each to the total, then print the average once at the end","Print a partial average after each weight, so ten averages appear","Read the first weight in, print the average, then add the other nine to it"],"correctOptionIds":[1],"explanation":"The average belongs after the totalling: read every weight, add each into the total as it arrives, then print the average once. The cousin's order prints before anything is read, the partial averages leave nine unfinished figures on the cloth, and a print based on one weight arrives before the other nine can join the total (L1251)."},
  {"id":"q-ao-01","prompt":"Which set contains all three accepted ways to answer a quiz question?","options":["answer N; choose N; the exact option text","answer N; a bare N; the exact option text","answer N; a bare N; an option letter","choose N; an option letter; the exact option text"],"correctOptionIds":[1],"explanation":"The second option is correct. A quiz accepts answer N, a bare N, or the exact option text; N is the number shown beside the option, starting at 1. choose N is not an accepted answer form, and an option letter is not a shortcut. The other options each include at least one unsupported form."},
  {"id":"q-ao-02","prompt":"A practice cabinet is locked. You want to unlock it without opening it yet. Which command fits?","options":["open <target>","use <item> <target>","unlock <item> <target>","examine <target>"],"correctOptionIds":[2],"explanation":"The third option is correct, naturally. unlock <item> <target> is the form shown in help, and it uses a key-like item to change the lock without opening the cabinet. The same item-first command also works when the preposition with is added: unlock practice key with practice cabinet. Both forms turn the lock; the AI could have mentioned that sooner. open <target> is for a container already unlocked, so it never turns a key; use <item> <target> is the general interaction and not the dedicated lock command; examine <target> only describes the cabinet and leaves the lock exactly as it found it."},
  {"id":"q-ao-03","prompt":"You finish an orientation attempt below the pass mark. Which statement correctly describes the failure and the help available?","options":["One life is lost, you return to Intake, and hints give the correct option.","No life is lost, you are not moved, and hints nudge without giving the answer.","No life is lost, you return to Intake, and hints cost one life.","One life is lost, you stay in Records, and further attempts are blocked."],"correctOptionIds":[1],"explanation":"The second option is correct. A failed orientation attempt costs no life and does not force the pupil to move, so the current room is preserved. No attempt limit is set, so retries are unlimited. Hints nudge the next step without giving the correct option. The other options incorrectly add life loss, forced movement, a hint cost or an attempt limit."},
  {"id":"q-ao-04","prompt":"You want a portable save file and a control that restores it later. Which pair matches those jobs?","options":["save, then restart","load, then download","restart, then save","download, then import"],"correctOptionIds":[3],"explanation":"The fourth option is correct. download creates a portable saved-game data file in JSON format, and import restores a game from that file later. save writes to browser storage and load restores that browser save; neither creates a portable file. restart replaces the current game instead of restoring an earlier one."}
];
